<?php
declare(strict_types=1);
ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function hw_json(int $status,array $payload):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($payload,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
function hw_audit(PDO $db,int $uid,string $action,int $id,int $school):void{$q=$db->prepare("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,'homework_assignment',?,?)");$q->execute([$uid,$action,$id,json_encode(['school_id'=>$school],JSON_THROW_ON_ERROR)]);}
if(!signed_in())hw_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))hw_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);$db=db();$uid=(int)$_SESSION['user_id'];$role=(string)$_SESSION['role'];
if($role==='pupil'){$q=$db->prepare("SELECT p.id pupil_id,p.school_id,p.class_level FROM pupil_accounts a JOIN pupils p ON p.id=a.pupil_id AND p.school_id=a.school_id WHERE a.user_id=? AND a.active=1 AND p.status='active' LIMIT 1");$q->execute([$uid]);$pupil=$q->fetch();if(!$pupil)hw_json(403,['ok'=>false,'message'=>'No active pupil record is linked.']);$school=(int)$pupil['school_id'];$pupilId=(int)$pupil['pupil_id'];if($_SERVER['REQUEST_METHOD']==='GET'){$q=$db->prepare("SELECT a.id,a.title,a.instructions,a.subject,a.due_date,a.created_at,u.name teacher_name,n.id material_id,n.subtopic material_subtopic,n.content material_content,s.response,s.status submission_status,s.submitted_at,s.feedback FROM homework_assignments a JOIN users u ON u.id=a.teacher_id LEFT JOIN learning_notes n ON n.id=a.learning_note_id LEFT JOIN pupil_homework_submissions s ON s.assignment_id=a.id AND s.school_id=a.school_id AND s.pupil_id=? WHERE a.school_id=? AND a.class_level=? AND a.status='published' AND (a.due_date IS NULL OR a.due_date>=DATE_SUB(CURRENT_DATE,INTERVAL 30 DAY)) ORDER BY (s.id IS NULL) DESC,a.due_date IS NULL,a.due_date,a.created_at DESC LIMIT 100");$q->execute([$pupilId,$school,$pupil['class_level']]);hw_json(200,['ok'=>true,'data'=>['assignments'=>$q->fetchAll()]]);}if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='submit_work'){verify_csrf();$id=filter_var($_POST['assignment_id']??null,FILTER_VALIDATE_INT);$response=trim((string)($_POST['response']??''));if(!$id||$response===''||mb_strlen($response)>12000)hw_json(422,['ok'=>false,'message'=>'Choose an assignment and enter a response of up to 12,000 characters.']);$db->beginTransaction();try{$q=$db->prepare("SELECT a.id FROM homework_assignments a WHERE a.id=? AND a.school_id=? AND a.class_level=? AND a.status='published'");$q->execute([$id,$school,$pupil['class_level']]);if(!$q->fetchColumn())throw new DomainException('This assignment is unavailable to your class.');$q=$db->prepare('SELECT id,status FROM pupil_homework_submissions WHERE assignment_id=? AND pupil_id=? FOR UPDATE');$q->execute([$id,$pupilId]);$existing=$q->fetch();if($existing&&$existing['status']==='reviewed')throw new DomainException('This response has already been reviewed and can no longer be changed.');if($existing){$q=$db->prepare("UPDATE pupil_homework_submissions SET response=?,submitted_at=CURRENT_TIMESTAMP,status='submitted' WHERE id=?");$q->execute([$response,$existing['id']]);}else{$q=$db->prepare("INSERT INTO pupil_homework_submissions(assignment_id,school_id,pupil_id,response) VALUES(?,?,?,?)");$q->execute([$id,$school,$pupilId,$response]);}$submissionAuditId=(int)($existing['id']??$db->lastInsertId());$q=$db->prepare("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,'submit','pupil_homework_submission',?,?)");$q->execute([$uid,$submissionAuditId,json_encode(['school_id'=>$school,'assignment_id'=>$id],JSON_THROW_ON_ERROR)]);$db->commit();hw_json(200,['ok'=>true,'message'=>'Your homework response was submitted.']);}catch(Throwable $e){$db->rollBack();hw_json($e instanceof DomainException?422:500,['ok'=>false,'message'=>$e instanceof DomainException?$e->getMessage():'Your response could not be submitted.']);}}hw_json(405,['ok'=>false,'message'=>'Unsupported homework request.']);}
$school=filter_var($_REQUEST['school_id']??null,FILTER_VALIDATE_INT);if(!$school)hw_json(422,['ok'=>false,'message'=>'Choose a school.']);$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())hw_json(403,['ok'=>false,'message'=>'That school is outside your access.']);$reviewRoles=['head_academic','headteacher','sub_director','director'];if(!in_array($role,array_merge(['teacher'],$reviewRoles),true))hw_json(403,['ok'=>false,'message'=>'Your role cannot manage homework.']);$canReview=in_array($role,$reviewRoles,true);
if($_SERVER['REQUEST_METHOD']==='GET'){$view=(string)($_GET['view']??'list');if($view==='catalog'){$q=$db->prepare('SELECT c.id class_id,c.name class_name,s.id subject_id,s.name subject_name FROM teacher_assignments a JOIN school_classes c ON c.school_id=a.school_id AND c.name=a.class_level JOIN school_class_subjects s ON s.class_id=c.id AND s.name=a.subject WHERE a.user_id=? AND a.school_id=? AND a.active=1 ORDER BY c.name,s.name');$q->execute([$uid,$school]);$assignments=$q->fetchAll();if($role==='teacher'){$q=$db->prepare("SELECT n.id,n.subtopic,n.class_level,n.subject FROM learning_notes n WHERE n.status='published' AND ((n.note_type='teacher' AND EXISTS(SELECT 1 FROM teacher_assignments a JOIN school_memberships m ON m.school_id=a.school_id AND m.user_id=a.user_id WHERE a.user_id=? AND a.school_id=? AND a.active=1 AND a.class_level=n.class_level AND a.subject=n.subject AND n.school_id=a.school_id)) OR (n.note_type='central' AND n.school_id IS NULL AND EXISTS(SELECT 1 FROM teacher_assignments a JOIN school_memberships m ON m.school_id=a.school_id AND m.user_id=a.user_id JOIN school_classes c ON c.school_id=a.school_id AND c.name=a.class_level JOIN school_class_subjects cs ON cs.class_id=c.id AND cs.name=a.subject LEFT JOIN academic_classes ac ON ac.name=n.class_level LEFT JOIN academic_class_subjects ats ON ats.class_id=ac.id AND ats.name=n.subject WHERE a.user_id=? AND a.school_id=? AND a.active=1 AND (c.name=n.class_level OR (ac.id IS NOT NULL AND c.core_class_id=ac.id)) AND (n.subject IS NULL OR n.subject='' OR cs.name=n.subject OR (ats.id IS NOT NULL AND cs.core_subject_id=ats.id))))) ORDER BY n.subtopic LIMIT 300");$q->execute([$uid,$school,$uid,$school]);}else{$q=$db->prepare("SELECT id,subtopic,class_level,subject FROM learning_notes WHERE school_id=? AND note_type='teacher' AND status='published' UNION SELECT id,subtopic,class_level,subject FROM learning_notes WHERE school_id IS NULL AND note_type='central' AND status='published' ORDER BY subtopic LIMIT 300");$q->execute([$school]);}hw_json(200,['ok'=>true,'data'=>['assignments'=>$assignments,'materials'=>$q->fetchAll()]]);}if($view==='submissions'){$id=filter_var($_GET['assignment_id']??null,FILTER_VALIDATE_INT);if(!$id)hw_json(422,['ok'=>false,'message'=>'Choose an assignment.']);$sql='SELECT a.id FROM homework_assignments a WHERE a.id=? AND a.school_id=?';$params=[$id,$school];if(!$canReview){$sql.=' AND a.teacher_id=?';$params[]=$uid;}$q=$db->prepare($sql);$q->execute($params);if(!$q->fetchColumn())hw_json(404,['ok'=>false,'message'=>'Assignment not found.']);$q=$db->prepare('SELECT s.id submission_id,s.pupil_id,s.response,s.status,s.submitted_at,s.feedback,p.first_name,p.middle_name,p.last_name,p.admission_number FROM pupil_homework_submissions s JOIN pupils p ON p.id=s.pupil_id AND p.school_id=s.school_id WHERE s.assignment_id=? AND s.school_id=? ORDER BY s.submitted_at DESC');$q->execute([$id,$school]);hw_json(200,['ok'=>true,'data'=>['submissions'=>$q->fetchAll()]]);}$sql='SELECT a.id,a.class_level,a.subject,a.title,a.due_date,a.status,a.created_at,u.name teacher_name,(SELECT COUNT(*) FROM pupil_homework_submissions s WHERE s.assignment_id=a.id AND s.school_id=a.school_id) submissions FROM homework_assignments a JOIN users u ON u.id=a.teacher_id WHERE a.school_id=?';$params=[$school];if(!$canReview){$sql.=' AND a.teacher_id=?';$params[]=$uid;}$sql.=' ORDER BY a.updated_at DESC LIMIT 100';$q=$db->prepare($sql);$q->execute($params);hw_json(200,['ok'=>true,'data'=>['assignments'=>$q->fetchAll(),'can_review'=>$canReview]]);}
if($_SERVER['REQUEST_METHOD']!=='POST')hw_json(405,['ok'=>false,'message'=>'Unsupported homework request.']);verify_csrf();$action=(string)($_POST['action']??'');if($action==='save_assignment'){if($role!=='teacher')hw_json(403,['ok'=>false,'message'=>'Only assigned teachers can create homework.']);$classId=filter_var($_POST['class_id']??null,FILTER_VALIDATE_INT);$subjectId=filter_var($_POST['subject_id']??null,FILTER_VALIDATE_INT);$title=trim((string)($_POST['title']??''));$instructions=trim((string)($_POST['instructions']??''));$due=trim((string)($_POST['due_date']??''));$noteId=filter_var($_POST['learning_note_id']??null,FILTER_VALIDATE_INT)?:null;$status=(string)($_POST['status']??'draft');if(!$classId||!$subjectId||$title===''||mb_strlen($title)>180||$instructions===''||mb_strlen($instructions)>12000||!in_array($status,['draft','published'],true)||($due!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$due)))hw_json(422,['ok'=>false,'message'=>'Complete the class, subject, title and instructions with valid lengths and dates.']);$q=$db->prepare('SELECT c.name class_level,s.name subject FROM teacher_assignments a JOIN school_classes c ON c.school_id=a.school_id AND c.name=a.class_level JOIN school_class_subjects s ON s.class_id=c.id AND s.name=a.subject WHERE a.user_id=? AND a.school_id=? AND a.active=1 AND c.id=? AND s.id=?');$q->execute([$uid,$school,$classId,$subjectId]);$assignment=$q->fetch();if(!$assignment)hw_json(403,['ok'=>false,'message'=>'You are not assigned to that class and subject.']);if($noteId){$q=$db->prepare("SELECT 1 FROM learning_notes WHERE id=? AND class_level=? AND status='published' AND ((note_type='teacher' AND school_id=?) OR (note_type='central' AND school_id IS NULL))");$q->execute([$noteId,$assignment['class_level'],$school]);if(!$q->fetchColumn())hw_json(422,['ok'=>false,'message'=>'Choose a published learning material for this class.']);}$db->beginTransaction();try{$q=$db->prepare('INSERT INTO homework_assignments(school_id,teacher_id,class_level,subject,title,instructions,due_date,learning_note_id,status) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$school,$uid,$assignment['class_level'],$assignment['subject'],$title,$instructions,$due?:null,$noteId,$status]);$id=(int)$db->lastInsertId();hw_audit($db,$uid,'create',$id,$school);$db->commit();hw_json(200,['ok'=>true,'message'=>$status==='published'?'Homework published to the class.':'Homework draft saved.','data'=>['id'=>$id]]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();hw_json(500,['ok'=>false,'message'=>'Homework could not be saved.']);}}if($action==='review_submission'){if(!$canReview&&$role!=='teacher')hw_json(403,['ok'=>false,'message'=>'You cannot review homework.']);$submissionId=filter_var($_POST['submission_id']??null,FILTER_VALIDATE_INT);$feedback=trim((string)($_POST['feedback']??''));if(!$submissionId||$feedback===''||mb_strlen($feedback)>4000)hw_json(422,['ok'=>false,'message'=>'Enter review feedback up to 4,000 characters.']);$sql='SELECT s.id,s.status FROM pupil_homework_submissions s JOIN homework_assignments a ON a.id=s.assignment_id AND a.school_id=s.school_id WHERE s.id=? AND s.school_id=?';$params=[$submissionId,$school];if(!$canReview){$sql.=' AND a.teacher_id=?';$params[]=$uid;}$sql.=' FOR UPDATE';$db->beginTransaction();try{$q=$db->prepare($sql);$q->execute($params);$row=$q->fetch();if(!$row)throw new DomainException('Submission not found.');$q=$db->prepare("UPDATE pupil_homework_submissions SET status='reviewed',feedback=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP WHERE id=?");$q->execute([$feedback,$uid,$submissionId]);hw_audit($db,$uid,'review',$submissionId,$school);$db->commit();hw_json(200,['ok'=>true,'message'=>'Feedback saved.']);}catch(Throwable $e){$db->rollBack();hw_json($e instanceof DomainException?404:500,['ok'=>false,'message'=>$e instanceof DomainException?$e->getMessage():'Feedback could not be saved.']);}}hw_json(422,['ok'=>false,'message'=>'Unknown homework action.']);
